package com.example.analyzeproject.application.service;
public record StockTradingPolicy(int swingWindow,int longWindow,int minimumBars,int longMinimumBars,int standardBars,double swingBuyAtr,double longBuyAtr,double swingStopAtr,double longStopAtr,double swingExtensionAtr,double longExtensionAtr,double targetBufferAtr,double minimumRewardRisk,double emaBuyLowerAtr,double swingEmaStopAtr,double longEmaStopAtr,double emaFirstR,double swingEmaSecondR,double longEmaSecondR) {
 public StockTradingPolicy {
  if(!Double.isFinite(swingWindow) || swingWindow<=0 || !Double.isFinite(longWindow) || longWindow<=0 || !Double.isFinite(minimumBars) || minimumBars<=0 || !Double.isFinite(longMinimumBars) || longMinimumBars<=0 || !Double.isFinite(standardBars) || standardBars<=0 || !Double.isFinite(swingBuyAtr) || swingBuyAtr<=0 || !Double.isFinite(longBuyAtr) || longBuyAtr<=0 || !Double.isFinite(swingStopAtr) || swingStopAtr<=0 || !Double.isFinite(longStopAtr) || longStopAtr<=0 || !Double.isFinite(swingExtensionAtr) || swingExtensionAtr<=0 || !Double.isFinite(longExtensionAtr) || longExtensionAtr<=0 || !Double.isFinite(targetBufferAtr) || targetBufferAtr<=0 || !Double.isFinite(minimumRewardRisk) || minimumRewardRisk<=0 || !Double.isFinite(emaBuyLowerAtr) || emaBuyLowerAtr<=0 || !Double.isFinite(swingEmaStopAtr) || swingEmaStopAtr<=0 || !Double.isFinite(longEmaStopAtr) || longEmaStopAtr<=0 || !Double.isFinite(emaFirstR) || emaFirstR<=0 || !Double.isFinite(swingEmaSecondR) || swingEmaSecondR<=0 || !Double.isFinite(longEmaSecondR) || longEmaSecondR<=0)throw new IllegalArgumentException("Trading policy values must be positive and finite");
  if(minimumBars<15 || longMinimumBars<minimumBars || standardBars<longMinimumBars || swingWindow<2 || longWindow<swingWindow || emaFirstR>=swingEmaSecondR || emaFirstR>=longEmaSecondR)throw new IllegalArgumentException("Inconsistent trading policy");
 }
}
